import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec4, smoothstep, uv, positionLocal, mix } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, BoxGeometry, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const rootGroup = new Group();
  const timelines = [];

  // --- 1. DESIGN TOKENS & PALETTE ---
  const colors = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradStart: '#1a1a22',
    gradEnd: '#111116'
  };

  // --- 2. BACKDROP GRAND STAGE ---
  // A backdrop plane ~7x6 at z = -2.5 carrying vertical gradient of gradientStops
  const backdropGeo = new PlaneGeometry(8.5, 6.5);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });
  // Vertical gradient shader node
  backdropMat.colorNode = mix(
    color(colors.gradEnd),
    color(colors.gradStart),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  rootGroup.add(backdrop);

  // --- 3. PANEL COMPONENT ---
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelDepth = 0.05;

  const panelGroup = new Group();
  panelGroup.position.set(0, 0, 0);
  rootGroup.add(panelGroup);

  // Main Panel Mesh
  const panelGeo = new BoxGeometry(panelWidth, panelHeight, panelDepth);
  const panelMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1
  });

  // Apply a subtle vertical color gradient to the panel face via TSL
  const localYNormalized = positionLocal.y.add(panelHeight / 2).div(panelHeight);
  panelMat.colorNode = mix(
    color(colors.gradEnd),
    color(colors.gradStart),
    localYNormalized
  );

  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.castShadow = true;
  panelMesh.receiveShadow = true;
  panelGroup.add(panelMesh);

  // 0.006-unit Hairline Border (Simulated with a slightly larger, very thin back plane/box or outline)
  const borderGeo = new BoxGeometry(panelWidth + 0.012, panelHeight + 0.012, panelDepth - 0.002);
  const borderMat = new MeshStandardNodeMaterial({
    color: '#26262f',
    roughness: 0.4,
    metalness: 0.3
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.001);
  panelGroup.add(borderMesh);

  // Shadow plane
  const shadowGeo = new PlaneGeometry(panelWidth * 1.3, panelHeight * 1.3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.4,
    depthWrite: false
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.1, -0.06);
  panelGroup.add(shadowMesh);

  // --- 4. TYPOGRAPHY & FLOATING TEXTS ---
  const textGroup = new Group();
  textGroup.position.set(0, 0, panelDepth / 2 + 0.03); // Floating translateZ +0.03
  panelGroup.add(textGroup);

  // Get raw items safely
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const quoteMarkText = textItems[0]?.text ?? '“';
  const quoteBodyText = textItems[1]?.text ?? "The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.";
  const attributionText = textItems[2]?.text ?? "M. OKAFOR";
  const captionText = textItems[3]?.text ?? "COLLECTOR SINCE 2019";

  // Oversized Quote Mark at Top-Left
  const quoteMarkMesh = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 56, // scaled slightly to fit inside panel elegantly
    color: colors.accent,
    align: 'left'
  });
  // Position top-left inside panel: padding is 0.5 units
  quoteMarkMesh.position.set(-panelWidth / 2 + 0.4, panelHeight / 2 - 0.38, 0.01);
  textGroup.add(quoteMarkMesh);

  // Quote Paragraph Body
  const quoteBodyMesh = ctx.fontAtlas.createText(quoteBodyText, {
    fontSize: 16.5,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 640,
    letterSpacingPx: 0
  });
  quoteBodyMesh.position.set(-panelWidth / 2 + 0.4, panelHeight / 2 - 0.88, 0);
  textGroup.add(quoteBodyMesh);

  // Accent Rule Decorator (0.2w x 0.02h scene units, red, emissive 1.4)
  const ruleGeo = new BoxGeometry(0.2, 0.02, 0.01);
  const ruleMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.4
  });
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  // Seated 0.25 below quote
  ruleMesh.position.set(-panelWidth / 2 + 0.4 + 0.1, panelHeight / 2 - 1.45, 0.005);
  textGroup.add(ruleMesh);

  // Attribution Text
  const attributionMesh = ctx.fontAtlas.createText(attributionText, {
    fontSize: 11,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 3
  });
  attributionMesh.position.set(-panelWidth / 2 + 0.75, panelHeight / 2 - 1.43, 0);
  textGroup.add(attributionMesh);

  // Caption Text
  const captionMesh = ctx.fontAtlas.createText(captionText, {
    fontSize: 8,
    color: '#8e8e9f',
    align: 'left',
    letterSpacingPx: 4
  });
  captionMesh.position.set(-panelWidth / 2 + 0.75, panelHeight / 2 - 1.58, 0);
  textGroup.add(captionMesh);

  // --- 5. ENTRANCE TRANSITION & ANIMATIONS ---
  // Initially hide elements for the staggered load-in
  panelGroup.position.y = -0.2;
  panelGroup.scale.set(0.95, 0.95, 0.95);
  const matsToFade = [panelMat, borderMat, shadowMat];
  matsToFade.forEach(m => {
    m.transparent = true;
    m.opacity = 0;
  });

  quoteMarkMesh.scale.set(0.01, 0.01, 0.01);
  quoteBodyMesh.scale.set(0.9, 0.9, 0.9);
  quoteBodyMesh.visible = false;
  attributionMesh.visible = false;
  captionMesh.visible = false;
  ruleMesh.scale.set(0, 1, 1);

  const t1 = gsap.timeline({ delay: 0.1 });
  timelines.push(t1);

  // Panel fade-up
  t1.to(panelGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);

  t1.to(panelGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.7,
    ease: 'power2.out'
  }, 0);

  matsToFade.forEach(m => {
    t1.to(m, {
      opacity: 1,
      duration: 0.6,
      ease: 'power2.out'
    }, 0);
  });

  // Quote-mark entrance (weighted-settle scale 1.04 -> 1.0)
  t1.to(quoteMarkMesh.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.5,
    ease: 'back.out(1.7)',
    onStart: () => { quoteBodyMesh.visible = true; }
  }, 0.35);

  t1.to(quoteMarkMesh.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.4,
    ease: 'power4.out'
  }, 0.85);

  // Other texts stagger-reveal
  t1.to(quoteBodyMesh.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.5,
    ease: 'power2.out'
  }, 0.45);

  t1.to(ruleMesh.scale, {
    x: 1,
    duration: 0.4,
    ease: 'power2.out',
    onStart: () => {
      attributionMesh.visible = true;
      captionMesh.visible = true;
    }
  }, 0.55);

  // Return context-managed life-cycle cleanup
  rootGroup.userData = {
    cleanup() {
      timelines.forEach(tl => tl.kill());
      panelGeo.dispose();
      panelMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      shadowGeo.dispose();
      shadowMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
      ruleGeo.dispose();
      ruleMat.dispose();
    }
  };

  return rootGroup;
}
